key.harness:
`timescale 1ns/1ps
// The grading testbench. Four things the sample one does not do:
// hold din high for many cycles, come out of reset with din already
// high, count two separate edges, and assert reset while a pulse
// would otherwise be produced.
module tb;
  logic clk = 1'b0, rst = 1'b1, din = 1'b0, rise;
  int pulses = 0;

  edge_detect dut (.clk(clk), .rst(rst), .din(din), .rise(rise));

  always #5 clk = ~clk;
  always @(negedge clk) if (rise) pulses++;

  initial begin
    @(posedge clk); @(negedge clk);
    $display("CHECK after_reset 0 %b AT %0d", rise, $time);
    rst = 1'b0;

    @(negedge clk) din = 1'b1;
    @(posedge clk); #1;
    $display("CHECK one_cycle_later 1 %b AT %0d", rise, $time);
    @(posedge clk); #1;
    $display("CHECK single_pulse 0 %b AT %0d", rise, $time);

    // Held high for six more cycles: still exactly one pulse in total.
    repeat (6) @(posedge clk);
    @(negedge clk); #1;
    $display("CHECK held_high_once 1 %0d AT %0d", pulses, $time);

    @(negedge clk) din = 1'b0;
    @(posedge clk); #1;
    $display("CHECK no_fall 0 %b AT %0d", rise, $time);

    // A second edge, later, must be detected too: a design that
    // remembers "I have already fired" rather than the previous sample
    // passes everything above and fails here.
    @(negedge clk) din = 1'b1;
    @(posedge clk); @(negedge clk); #1;
    $display("CHECK two_edges 2 %0d AT %0d", pulses, $time);

    // Reset with din high, then release. The first sample after reset
    // is not an edge, so no pulse.
    begin
      int was;
      rst = 1'b1; din = 1'b1;
      repeat (2) @(posedge clk);
      @(negedge clk); #1;
      was = pulses;
      rst = 1'b0;
      repeat (3) @(posedge clk);
      @(negedge clk); #1;
      $display("CHECK reset_with_din_high %0d %0d AT %0d", was, pulses, $time);
    end

    // Reset asserted in the same cycle a pulse would be produced:
    // reset wins, and rise is low.
    begin
      din = 1'b0;
      @(negedge clk);
      din = 1'b1; rst = 1'b1;
      @(posedge clk); #1;
      $display("CHECK rst_clears 0 %b AT %0d", rise, $time);
    end

    $display("DONE 8");
    $finish;
  end
endmodule

reference.sv:
module edge_detect (
  input  logic clk,
  input  logic rst,
  input  logic din,
  output logic rise
);

  logic din_prev;

  always_ff @(posedge clk) begin
    if (rst) begin
      din_prev <= 1'b1;   // see the explanation: not 0
      rise     <= 1'b0;
    end else begin
      rise     <= din & ~din_prev;
      din_prev <= din;
    end
  end

endmodule
